{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE SNITCH_DB.MAPLEMONK.LUGGAGE_MASTER AS WITH offline AS ( SELECT o.ORDER_DATE, o.branch_code AS MARKETPLACE, o.MARKETPLACE_MAPPED, o.phone, o.order_timestamp, o.order_name AS Order_id, o.SKU, o.sku_group, CASE WHEN o.sku LIKE \'4MTL0001%\' THEN \'BLINK\' WHEN o.SKU LIKE \'4MTL0002%\' THEN \'VITO\' WHEN o.SKU LIKE \'4MTL0003%\' THEN \'RUBIK\' ELSE \'Other\' END AS Style, CASE WHEN RIGHT(o.SKU,1) LIKE \'3\' THEN \'SET-3\' WHEN RIGHT(o.sku,1) LIKE \'2\' THEN \'SET-2\' ELSE RIGHT(o.SKU,1) END AS SIZE, RIGHT(LEFT(o.SKU,11),2) AS COLOR, s.\"Shipping Address City\" AS CITY, s.state AS STATE, s.\"Shipping Address Pincode\" AS PINCODE, o.SUBORDER_QUANTITY AS QTY, o.MRP, ROUND(o.SELLING_PRICE,0) AS SELLING_PRICE, o.COGS_PRICE AS COGS, ROUND(o.SELLING_PRICE,0) - o.COGS_PRICE AS GROSS_PROFIT, \'\' AS shippingpackagecode, \'\' AS shippingpackagestatus, \'\' AS shipping_courier, CAST(NULL AS DATE) AS delivered_date, \'\' AS AWB, \'\' AS warehouse_name, CAST(NULL AS VARCHAR) AS order_status, CAST(NULL AS VARCHAR) AS sale_order_item_status FROM snitch_db.maplemonk.store_fact_items_offline o LEFT JOIN GS_STORE_DETAILS s ON o.branch_code = s.branch_code WHERE o.sku_group LIKE \'4MTL0%\' AND o.doc_prefix NOT LIKE \'%QCOM%\' AND o.doc_prefix NOT LIKE \'%OMS%\' ), online AS ( SELECT order_date, marketplace, marketplace_mapped, CAST(NULL AS VARCHAR) AS phone, order_timestamp, order_name AS Order_id, sku, sku_group, CASE WHEN sku LIKE \'4MTL0001%\' THEN \'BLINK\' WHEN SKU LIKE \'4MTL0002%\' THEN \'VITO\' WHEN SKU LIKE \'4MTL0003%\' THEN \'RUBIK\' ELSE \'Other\' END AS Style, CASE WHEN RIGHT(SKU,1) LIKE \'3\' THEN \'SET-3\' WHEN RIGHT(sku,1) LIKE \'2\' THEN \'SET-2\' ELSE RIGHT(SKU,1) END AS SIZE, RIGHT(LEFT(SKU,11),2) AS COLOR, city, state, pincode, suborder_quantity AS QTY, mrp, selling_price AS SELLING_PRICE, cost AS COGS, selling_price - cost AS GROSS_PROFIT, shippingpackagecode, shippingpackagestatus, shipping_courier, delivered_date, AWB, warehouse_name, order_status, sale_order_item_status FROM snitch_db.maplemonk.unicommerce_fact_items_intermediate WHERE sku_group LIKE \'4MTL0%\' AND marketplace_mapped LIKE \'SHOPIFY\' ), combined_raw AS ( SELECT * FROM offline UNION ALL SELECT * FROM online ), combined AS ( SELECT c.*, ROW_NUMBER() OVER (ORDER BY (SELECT NULL)) AS combined_row_id FROM combined_raw c ), cp_base AS ( SELECT DISTINCT ORDER_ID, awb_number, pre_current_status, status, quantity_in_box, courier_partner, return_reason, sku_list, journey FROM cp_1 WHERE SKU_LIST LIKE \'%4MTL0%\' AND NOT ( journey IN (\'RTO\',\'Reverse\') AND status = \'CANCELLED\' ) ), matched AS ( SELECT c.combined_row_id, cp.awb_number, cp.pre_current_status, cp.status, cp.quantity_in_box, cp.courier_partner, cp.return_reason, cp.sku_list, cp.journey, ROW_NUMBER() OVER ( PARTITION BY c.combined_row_id ORDER BY CASE WHEN cp.journey IN (\'RTO\',\'Reverse\') THEN 0 ELSE 1 END ) AS rn FROM combined c LEFT JOIN cp_base cp ON c.Order_id = cp.ORDER_ID AND \',\' || REPLACE(cp.sku_list, \' \', \'\') || \',\' LIKE \'%,\' || c.SKU || \',%\' ), final_data AS ( SELECT c.*, m.awb_number, m.pre_current_status, m.status, m.quantity_in_box, m.courier_partner, m.return_reason, m.sku_list, m.journey, CASE WHEN m.journey = \'RTO\' THEN \'RTO\' WHEN m.journey = \'Reverse\' AND m.status IN ( \'DELIVERED\', \'INTRANSIT\', \'PENDING\', \'ORDER_PLACED\' ) THEN \'RETURNED\' WHEN m.journey = \'Reverse\' THEN m.status WHEN m.journey = \'Forward\' AND m.status = \'DELIVERED\' THEN \'DELIVERED\' WHEN m.journey = \'Forward\' THEN m.status WHEN c.sale_order_item_status = \'CANCELLED\' THEN \'CANCELLED\' ELSE c.sale_order_item_status END AS final_status FROM combined c LEFT JOIN matched m ON c.combined_row_id = m.combined_row_id AND m.rn = 1 ), store_returns_base AS ( SELECT branch_code, phone, sku, order_date, order_timestamp, COALESCE(suborder_quantity, 1) AS return_qty, ROW_NUMBER() OVER ( ORDER BY branch_code, phone, sku, order_timestamp, order_date ) AS return_id FROM snitch_db.maplemonk.store_returns_fact_items_final_check WHERE sku LIKE \'4MTL0%\' AND marketplace NOT LIKE \'%WH%\' AND order_id NOT LIKE \'%RTO%\' ), return_candidates AS ( SELECT sr.return_id, sr.branch_code, sr.phone, sr.sku, sr.order_timestamp AS return_timestamp, sr.return_qty, fd.combined_row_id, fd.Order_id AS sales_order_id, fd.order_timestamp AS sales_timestamp, fd.QTY AS sales_qty, DATEDIFF( \'second\', fd.order_timestamp, sr.order_timestamp ) AS timestamp_gap_seconds, ROW_NUMBER() OVER ( PARTITION BY sr.return_id ORDER BY DATEDIFF( \'second\', fd.order_timestamp, sr.order_timestamp ) ASC, fd.order_timestamp DESC, fd.combined_row_id ) AS candidate_rank FROM store_returns_base sr INNER JOIN final_data fd ON fd.MARKETPLACE_MAPPED <> \'SHOPIFY\' AND fd.MARKETPLACE = sr.branch_code AND fd.phone = sr.phone AND fd.sku_group = sr.sku AND fd.order_timestamp < sr.order_timestamp AND fd.order_timestamp IS NOT NULL ), closest_return_match AS ( SELECT return_id, combined_row_id, return_timestamp, timestamp_gap_seconds, return_qty FROM return_candidates WHERE candidate_rank = 1 ), offline_return_mapping_ranked AS ( SELECT crm.return_id, crm.combined_row_id, crm.return_timestamp, crm.timestamp_gap_seconds, crm.return_qty, ROW_NUMBER() OVER ( PARTITION BY crm.combined_row_id ORDER BY crm.return_timestamp ASC, crm.timestamp_gap_seconds ASC, crm.return_id ASC ) AS sales_return_rank FROM closest_return_match crm ), offline_return_mapping AS ( SELECT return_id, combined_row_id, return_timestamp, timestamp_gap_seconds, return_qty FROM offline_return_mapping_ranked WHERE sales_return_rank = 1 ), final_data_v2 AS ( SELECT fd.*, CASE WHEN fd.MARKETPLACE_MAPPED <> \'SHOPIFY\' AND orm.combined_row_id IS NOT NULL THEN \'RETURNED\' WHEN fd.MARKETPLACE_MAPPED <> \'SHOPIFY\' THEN \'NET\' ELSE fd.final_status END AS final_status_v2, CASE WHEN fd.MARKETPLACE_MAPPED <> \'SHOPIFY\' AND orm.combined_row_id IS NOT NULL THEN TRUE ELSE FALSE END AS is_store_return FROM final_data fd LEFT JOIN offline_return_mapping orm ON fd.combined_row_id = orm.combined_row_id ), output_data AS ( SELECT fd2.*, CASE WHEN fd2.MARKETPLACE_MAPPED <> \'SHOPIFY\' THEN CASE WHEN fd2.is_store_return = TRUE THEN \'GROSS_ONLY\' ELSE \'NET\' END ELSE CASE WHEN fd2.journey = \'Reverse\' THEN \'GROSS_ONLY\' WHEN fd2.journey = \'RTO\' THEN \'GROSS_ONLY\' WHEN fd2.final_status_v2 IN ( \'DELIVERED\', \'INTRANSIT\', \'ORDER_PLACED\', \'PACKED\' ) THEN \'NET\' ELSE \'GROSS_ONLY\' END END AS SALES_TYPE FROM final_data_v2 fd2 ) SELECT DISTINCT od.* EXCLUDE ( combined_row_id, final_status, final_status_v2, is_store_return ), od.final_status_v2 AS final_status, od.SALES_TYPE FROM output_data od ORDER BY od.ORDER_DATE DESC, MARKETPLACE, Order_id ;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from SNITCH_DB.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            